import { Routes } from "@angular/router";
import { AttendanceComponent } from "./attendance/attendance.component";
import { AttendanceAddComponent } from "./attendance/attendance-add/attendance-add.component";
import { ClassRoutineComponent } from "./class-routine/class-routine.component";
import { ClassRoutineAddComponent } from "./class-routine/class-routine-add/class-routine-add.component";
import { ClasszComponent } from "./classz/classz.component";
import { ClasszAddComponent } from "./classz/classz-add/classz-add.component";
import { InstituteComponent } from "./institute/institute.component";
import { InstituteAddComponent } from "./institute/institute-add/institute-add.component";
import { LibraryComponent } from "./library/library.component";
import { LibraryAddComponent } from "./library/library-add/library-add.component";
import { StudentPromoteComponent } from "./student-promote/student-promote.component";
import { StudentPromoteAddComponent } from "./student-promote/student-promote-add/student-promote-add.component";
import { SectionzComponent } from "./sectionz/sectionz.component";
import { SectionzAddComponent } from "./sectionz/sectionz-add/sectionz-add.component";
import { RoutezFeatureModule } from "@_core/_route";

export const Routez: Routes = new RoutezFeatureModule(
  ['Education', 'Attendance'],
  'feature/education'
)
.feature(
  AttendanceComponent,
  AttendanceAddComponent,
  'attendance',
  'Attendance'
)
.feature(
  ClassRoutineComponent,
  ClassRoutineAddComponent,
  'class-routine',
  'Class Routine'
)
.feature(
  ClasszComponent,
  ClasszAddComponent,
  'classz',
  'Class'
)
.feature(
  InstituteComponent,
  InstituteAddComponent,
  'institute',
  'Institute'
)
.feature(
  LibraryComponent,
  LibraryAddComponent,
  'library',
  'Library'
)
.feature(
  SectionzComponent,
  SectionzAddComponent,
  'section',
  'Section'
)
.feature(
  StudentPromoteComponent,
  StudentPromoteAddComponent,
  'student-promote',
  'Student Promote'
)
.build();
